/**
 * @file font_config.h
 * @brief Font configuration for display
 *
 * All fonts are pre-rendered at native pixel sizes to avoid scaling artifacts
 * on the 240x240 GC9A01 display. Each size is optimized for a specific use:
 *
 *   10pt - Scale numbers (alphabet ring markers)
 *   12pt - Arc text (IPA transcription, word display)
 *   16pt - Center phoneme display (large, prominent)
 */

#pragma once

#ifndef U8G2_FONT_SECTION
#define U8G2_FONT_SECTION(name)
#endif

// Built-in LovyanGFX fonts (always available)
#define LGFX_USE_V1
#include <LovyanGFX.hpp>

// IPA fonts (generated by tools/setup_and_generate_fonts.sh)
#include "fonts/noto_sans_ipa_10.h"
#include "fonts/noto_sans_ipa_12.h"
#include "fonts/noto_sans_ipa_16.h"

#ifdef CONFIG_FORMANT_DISPLAY_IPA_FONT
    // Extern instances defined in src/font_instances.cpp
    extern const lgfx::U8g2font noto_sans_ipa_10_lgfx;
    extern const lgfx::U8g2font noto_sans_ipa_12_lgfx;
    extern const lgfx::U8g2font noto_sans_ipa_16_lgfx;

    #define FONT_SCALE      &noto_sans_ipa_10_lgfx  // Alphabet ring scale numbers
    #define FONT_IPA_12     &noto_sans_ipa_12_lgfx  // Arc text (IPA + word)
    #define FONT_IPA_16     &noto_sans_ipa_16_lgfx  // Center phoneme
    #define HAS_IPA_FONTS 1
#else
    // Use ASCII-only fallback fonts
    #define FONT_SCALE      &fonts::FreeSans9pt7b
    #define FONT_IPA_12     &fonts::FreeSans9pt7b
    #define FONT_IPA_16     &fonts::FreeSans9pt7b
    #define HAS_IPA_FONTS 0
#endif

// Font information
#if HAS_IPA_FONTS
    #define FONT_SUPPORTS_IPA true
    #define FONT_TYPE "Noto Sans (IPA)"
#else
    #define FONT_SUPPORTS_IPA false
    #define FONT_TYPE "FreeSans (ASCII)"
#endif
